CREATE TABLE IF NOT EXISTS billing_events (event_id text PRIMARY KEY, event_type text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS entitlements (workspace_id uuid PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE, plan text NOT NULL DEFAULT 'free', monthly_credits integer NOT NULL DEFAULT 25, max_projects integer NOT NULL DEFAULT 10, max_generation_resolution text NOT NULL DEFAULT '1280x720', advanced_analytics boolean NOT NULL DEFAULT false, team_members integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS oauth_states (state_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, provider text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS oauth_states_expiry_idx ON oauth_states(expires_at);

CREATE TABLE IF NOT EXISTS templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, created_by uuid NOT NULL REFERENCES users(id), name text NOT NULL, description text NOT NULL DEFAULT '', document jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE INDEX IF NOT EXISTS templates_workspace_updated_idx ON templates(workspace_id,updated_at DESC) WHERE deleted_at IS NULL;
